int is_palindrome(char s[]) {
    int n = 0;
    while (s[n] != '\0') n++;
    for (int i = 0; i < n / 2; i++) {
        if (s[i] != s[n - 1 - i]) return 0;
    }
    return 1;
}

int is_palindrome(char s[]) {
    int n = 0;
    while (s[n] != '\0') n++;
    int i = 0;
    int j = n - 1;
    while (i < j) {
        if (s[i] != s[j]) return 0;
        i++;
        j--;
    }
    return 1;
}

